/**
 * TCL Automation Index Loader
 *
 * Loads the pre-built automation_index.json (generated by scripts/index-tcl-libs.js)
 * and provides findRelevantProcs(text) for use by Stage 4 classifier and Stage 7 generator.
 *
 * The index is loaded ONCE at module require-time (in-process cache).
 * Call reloadIndex() after running the indexer to pick up updates without restarting.
 */

const fs   = require('fs');
const path = require('path');

const INDEX_PATH = path.resolve(__dirname, '../../../data/tcl_framework_docs/automation_index.json');

// Area keyword map — same logic as in the indexer
const AREA_KEYWORDS = [
  ['SNMP',      /snmp|mib.*snmp/i],
  ['BGP',       /\bbgp\b/i],
  ['OSPF',      /\bospf\b/i],
  ['MPLS',      /\bmpls\b|ldp|rsvp/i],
  ['VLAN',      /\bvlan\b|802\.1q/i],
  ['ACL',       /\bacl\b|access.?control/i],
  ['STP',       /\bstp\b|rstp|mstp|spanning.?tree/i],
  ['VXLAN',     /\bvxlan\b/i],
  ['PTP',       /\bptp\b|precision.?time/i],
  ['BFD',       /\bbfd\b|bidirectional.?forward/i],
  ['LACP',      /\blacp\b|link.?aggregat/i],
  ['LLDP',      /\blldp\b/i],
  ['QoS',       /\bqos\b|quality.?of.?service|\bcos\b/i],
  ['Multicast', /multicast|igmp|\bpim\b/i],
  ['DHCP',      /\bdhcp\b|bootp/i],
  ['DOT1X',     /802\.1x|dot.?1x|port.?auth/i],
  ['MIB',       /\bmib\b/i],
  ['CLI',       /\bcli\b|command.?line/i],
  ['Traffic',   /traffic|ixia|packet.?gen|send.?frame/i],
  ['CFM',       /\bcfm\b|\boam\b/i],
];

let _index = null;

function loadIndex() {
  if (!fs.existsSync(INDEX_PATH)) {
    console.warn('[tclIndex] automation_index.json not found. Run scripts/index-tcl-libs.js to build it.');
    return null;
  }
  try {
    _index = JSON.parse(fs.readFileSync(INDEX_PATH, 'utf8'));
    console.log(`[tclIndex] Loaded ${_index.total_procs} procs from ${_index.total_files} files (indexed ${_index.indexed_at})`);
    return _index;
  } catch (e) {
    console.error('[tclIndex] Failed to load index:', e.message);
    return null;
  }
}

// Load immediately on require
loadIndex();

/**
 * Reload the index from disk (call this after re-running the indexer).
 */
function reloadIndex() {
  return loadIndex();
}

/**
 * Given free text (e.g. a TC title or description), return the most relevant
 * proc entries from the index.
 *
 * Strategy:
 *  1. Detect matching areas from text keywords
 *  2. Return procs from those areas (up to maxProcs)
 *  3. Fall back to name-substring match across all_procs if no area match
 *
 * @param {string} text - TC title or combined description
 * @param {number} maxProcs - max procs to return (default 15)
 * @returns {{ name, params, file, area }[]}
 */
function findRelevantProcs(text, maxProcs = 15) {
  if (!_index) return [];

  const matchedAreas = [];
  for (const [area, re] of AREA_KEYWORDS) {
    if (re.test(text) && _index.areas[area]) {
      matchedAreas.push(area);
    }
  }

  let results = [];

  if (matchedAreas.length > 0) {
    // Gather procs from each matched area
    for (const area of matchedAreas) {
      results.push(...(_index.areas[area] || []));
    }
  } else {
    // Fallback: substring match on proc names
    const words = text.toLowerCase().split(/\W+/).filter(w => w.length > 3);
    results = _index.all_procs.filter(p =>
      words.some(w => p.name.toLowerCase().includes(w))
    );
  }

  // Deduplicate and limit
  const seen = new Set();
  return results.filter(p => {
    if (seen.has(p.name)) return false;
    seen.add(p.name);
    return true;
  }).slice(0, maxProcs);
}

/**
 * Build a compact text snippet of relevant procs for inclusion in an LLM prompt.
 * @param {string} text
 * @param {number} maxProcs
 * @returns {string}
 */
function buildProcContext(text, maxProcs = 15) {
  const procs = findRelevantProcs(text, maxProcs);
  if (procs.length === 0) return '';

  const lines = procs.map(p =>
    `  proc ${p.name} {${p.params}}  ;# from ${p.file}`
  );
  return lines.join('\n');
}

/**
 * Get index metadata (for the /api/reindex status endpoint).
 */
function getIndexMeta() {
  if (!_index) return { loaded: false };
  return {
    loaded:      true,
    indexed_at:  _index.indexed_at,
    total_files: _index.total_files,
    total_procs: _index.total_procs,
    areas:       Object.fromEntries(
      Object.entries(_index.areas).map(([k, v]) => [k, v.length])
    ),
  };
}

module.exports = { findRelevantProcs, buildProcContext, reloadIndex, getIndexMeta };
